checksum_guard.main.py:
"""Exit 0 only when the digest matches; 2 for either failure."""
import sys

from verify import matches


def main(argv):
    if len(argv) != 2:
        print("usage: main.py FILE SHA256")
        return 2
    try:
        ok = matches(argv[0], argv[1])
    except FileNotFoundError:
        print("missing file")
        return 2
    if not ok:
        print("checksum mismatch")
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

