guard_after_normalise.appender.py:
"""Append a fragment, refusing one that does not end with a newline."""
import sys


def read_norm(path):
    with open(path, encoding="utf-8") as fh:
        return fh.read().replace(chr(13) + chr(10), chr(10)).replace(chr(13), chr(10))


def main(path):
    body = read_norm(path)
    if not body.endswith(chr(10)):
        print("REFUSING: " + path + " is not newline-terminated")
        return 1
    print("ok")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1]))

