label_parser.labels.py:
"""Read the severity token an instrument puts at the head of its own line."""
LABEL_MAX = 16


def label_of(line):
    s = (line or "").lstrip()
    if not s.startswith("["):
        return None
    j = s.find("]")
    if j < 2 or j > LABEL_MAX:
        return None
    tok = s[1:j]
    if not tok or not all(ch.isupper() or ch in "-_" for ch in tok):
        return None
    return tok

