notify_path.notify.py:
"""Send one alert, then append a row to the delivery ledger.

The ledger lives in the operator's home directory, next to the other state files.
"""
import json
import os


def ledger_path():
    return os.path.join(os.path.expanduser(chr(126)), '.omni_brain', 'notify_delivery.jsonl')


def notify(title, body):
    ok = os.system('logger -t estate-notify ' + title) == 0
    row = {'title': title, 'body': body, 'sent': ok}
    with open(ledger_path(), 'a') as fh:
        fh.write(json.dumps(row) + chr(10))
    return 0 if ok else 1


if __name__ == '__main__':
    raise SystemExit(notify('disk full', 'root at 98 percent'))

