retry_bounded.retry.py:
"""Retry a flaky call a bounded number of times, then give up loudly."""
import time

ATTEMPTS = 4


def attempt_then_backoff(fn, sleep=time.sleep):
    delay = 0.05
    for _ in range(ATTEMPTS):
        try:
            return fn()
        except OSError:
            sleep(delay)
            delay *= 2
    raise RuntimeError("gave up after %d attempts" % ATTEMPTS)

