space_report.diskcheck.py:
"""Check that the data volume has room, and tell cron whether it does."""
import shutil
import sys

FLOOR_GB = 5


def free_gb(path="/srv/data"):
    return shutil.disk_usage(path).free // (1024 ** 3)


def main():
    free = free_gb()
    if free < FLOOR_GB:
        print("LOW SPACE: %dGB" % free)
    else:
        print("space fine: %dGB" % free)
    return 0


if __name__ == "__main__":
    sys.exit(main())

